import re

START = re.compile(r'^\s*(?P<num>\d+)\s+(?P<flags>[A-Z]*)\s*(?P<rest>.*?)\s*$')
KV = re.compile(r'([A-Za-z][\w-]*)=("[^"]*"|\S+(?: \d{1,2}:\d\d:\d\d)?)')

def add_pairs(rec, text):
    for m in KV.finditer(text):
        v = m.group(2)
        if v.startswith('"') and v.endswith('"') and len(v) >= 2:
            v = v[1:-1]
        rec[m.group(1)] = v

def parse(lines):
    skip = []
    recs = []
    used = []
    cur = None
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        if re.match(r'^\s*\[.*\]\s*>', line) or re.match(r'^\s*Flags:', line):
            skip.append(i)
            continue
        m = START.match(line)
        if m:
            cur = {'#': m.group('num'), 'flags': m.group('flags'), 'comment': ''}
            recs.append(cur)
            used.append(i)
            rest = m.group('rest')
            if rest.startswith(';;;'):
                cur['comment'] = rest[3:].strip()
            else:
                add_pairs(cur, rest)
            continue
        if cur is not None and line[:1].isspace():
            s = line.strip()
            if s.startswith(';;;'):
                cur['comment'] = s[3:].strip()
            else:
                add_pairs(cur, s)
            used.append(i)
    keys = []
    for r in recs:
        for k in r:
            if k not in keys:
                keys.append(k)
    rows = [{k: r.get(k, '') for k in keys} for r in recs]
    blocks = []
    if rows:
        blocks.append({'name': 'interfaces', 'kind': 'table', 'lines': used, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
